import * as T from '../vendor/three.module.js';
export function createOutfitFigure(items={},textures={}){
 const root=new T.Group(),materials=[],geometries=[];
 const mat=(color,slot)=>{const photo=textures[slot];const m=new T.MeshStandardMaterial({color:photo?'#ffffff':color,map:photo||null,roughness:.74,metalness:.06});materials.push(m);return m};
 const skin=mat('#c5b8aa'),dark=mat('#514943');
 function mesh(g,m,x,y,z,sx=1,sy=1,sz=1){geometries.push(g);const o=new T.Mesh(g,m);o.position.set(x,y,z);o.scale.set(sx,sy,sz);root.add(o);return o}
 const ball=(m,x,y,z,sx,sy,sz)=>mesh(new T.SphereGeometry(1,24,18),m,x,y,z,sx,sy,sz);
 const tube=(m,x,y,z,top,bottom,height)=>mesh(new T.CylinderGeometry(top,bottom,height,24),m,x,y,z);
 ball(skin,0,2.62,0,.16,.23,.16);tube(skin,0,2.35,0,.085,.085,.19);ball(skin,0,1.95,0,.29,.40,.15);ball(skin,0,1.51,0,.245,.20,.15);
 for(const side of [-1,1]){tube(skin,side*.145,.94,0,.10,.07,1.04);ball(skin,side*.36,1.70,0,.073,.44,.072);ball(skin,side*.39,1.23,0,.062,.095,.05);ball(dark,side*.145,.16,.065,.09,.10,.18)}
 const top=items.top;if(top){const m=mat(top.color,'top');tube(m,0,1.98,0,.27,.29,.61).scale.z=.62;const long=top.shape!=='tshirt';for(const side of [-1,1]){const arm=tube(m,side*.335,long?1.85:2.02,0,.095,.085,long?.62:.28);arm.rotation.z=side*.16}if(top.shape==='hoodie'){ball(m,0,2.30,-.075,.19,.12,.15);mesh(new T.BoxGeometry(.21,.11,.015),m,0,1.85,.19)}if(top.shape==='shirt'){const button=mat('#c1b5a5');for(let i=0;i<5;i++)ball(button,0,2.17-i*.095,.185,.012,.012,.008)}}
 const bottom=items.bottom;if(bottom){const m=mat(bottom.color,'bottom');if(bottom.shape==='skirt')tube(m,0,1.25,0,.25,.38,.66).scale.z=.65;else{const short=bottom.shape==='shorts';tube(m,0,1.49,0,.255,.26,.20).scale.z=.65;for(const side of [-1,1])tube(m,side*.145,short?1.21:.94,0,.135,short?.135:.105,short?.48:1.05).scale.z=.9}}
 const outer=items.outer;if(outer){const m=mat(outer.color,'outer'),long=outer.shape==='coat';for(const side of [-1,1]){const panel=mesh(new T.BoxGeometry(.22,long?1.02:.64,.37),m,side*.185,long?1.81:1.98,0);panel.rotation.z=side*.025;const arm=tube(m,side*.35,1.84,0,.112,.092,.7);arm.rotation.z=side*.13;mesh(new T.BoxGeometry(.06,.24,.04),m,side*.10,2.16,.21).rotation.z=side*.25}}
 const shoes=items.shoes;if(shoes){const m=mat(shoes.color,'shoes'),sole=mat('#f2eee5');for(const side of [-1,1]){ball(m,side*.145,.18,.085,.12,.115,.23);mesh(new T.BoxGeometry(.22,.045,.4),sole,side*.145,.095,.085);if(shoes.shape==='boots')tube(m,side*.145,.32,0,.105,.12,.26)}}
 return {root,dispose(){geometries.forEach(g=>g.dispose());materials.forEach(m=>m.dispose())}};
}
export function mountOutfit(host,items){
 let renderer;try{renderer=new T.WebGLRenderer({antialias:true,alpha:true,powerPreference:'low-power'})}catch{return null}
 renderer.setPixelRatio(Math.min(devicePixelRatio||1,1.5));renderer.setClearColor('#e8e1d8',1);renderer.outputColorSpace=T.SRGBColorSpace;host.append(renderer.domElement);
 const scene=new T.Scene(),camera=new T.PerspectiveCamera(35,1,.1,30);camera.position.set(0,1.65,5.6);camera.lookAt(0,1.45,0);scene.add(new T.HemisphereLight('#fff8ea','#767481',3));for(const [x,z,power] of [[3,4,4],[-3,-2,3]]){const light=new T.DirectionalLight('#ffffff',power);light.position.set(x,4,z);scene.add(light)}
 const pedestalGeometry=new T.CylinderGeometry(.6,.65,.07,64),pedestalMaterial=new T.MeshStandardMaterial({color:'#cec1b1',roughness:.9});const pedestal=new T.Mesh(pedestalGeometry,pedestalMaterial);pedestal.position.y=.025;scene.add(pedestal);
 let figure=createOutfitFigure(items),rotation=0,disposed=false,textureVersion=0,ownedTextures=[];scene.add(figure.root);
 function draw(){if(disposed||!host.clientWidth||!host.clientHeight)return;renderer.setSize(host.clientWidth,host.clientHeight,false);camera.aspect=host.clientWidth/host.clientHeight;camera.updateProjectionMatrix();figure.root.rotation.y=rotation;renderer.render(scene,camera)}
 async function refreshImages(next){const version=++textureVersion;const requested=Object.entries(next).filter(([,x])=>x.image);host.dispatchEvent(new CustomEvent('outfit:textures',{detail:{loading:requested.length,failed:0,loaded:0}}));const results=await Promise.all(requested.map(async([slot,x])=>{try{const texture=await new T.TextureLoader().loadAsync('/api/product-image?url='+encodeURIComponent(x.image));texture.colorSpace=T.SRGBColorSpace;texture.anisotropy=Math.min(renderer.capabilities.getMaxAnisotropy(),4);return {slot,texture}}catch{return {slot,failed:true}}}));if(disposed||version!==textureVersion){results.forEach(x=>x.texture?.dispose());return}scene.remove(figure.root);figure.dispose();ownedTextures.forEach(t=>t.dispose());ownedTextures=results.flatMap(x=>x.texture?[x.texture]:[]);const textures=Object.fromEntries(results.filter(x=>x.texture).map(x=>[x.slot,x.texture]));figure=createOutfitFigure(next,textures);scene.add(figure.root);draw();host.dispatchEvent(new CustomEvent('outfit:textures',{detail:{loading:0,loaded:ownedTextures.length,failed:results.filter(x=>x.failed).length}}));}
 const observer=new ResizeObserver(draw);observer.observe(host);let pointer=null;
 const down=e=>{pointer={id:e.pointerId,x:e.clientX};renderer.domElement.setPointerCapture(e.pointerId)},move=e=>{if(pointer?.id!==e.pointerId)return;rotation+=(e.clientX-pointer.x)*.012;pointer.x=e.clientX;draw()},up=()=>{pointer=null};
 renderer.domElement.addEventListener('pointerdown',down);renderer.domElement.addEventListener('pointermove',move);renderer.domElement.addEventListener('pointerup',up);renderer.domElement.addEventListener('pointercancel',up);renderer.domElement.style.touchAction='pan-y pinch-zoom';
 refreshImages(items);draw();return {update(items){scene.remove(figure.root);figure.dispose();figure=createOutfitFigure(items);scene.add(figure.root);draw();refreshImages(items)},rotate(delta){rotation+=delta;draw()},front(){rotation=0;draw()},dispose(){disposed=true;textureVersion++;ownedTextures.forEach(t=>t.dispose());observer.disconnect();renderer.domElement.remove();figure.dispose();pedestalGeometry.dispose();pedestalMaterial.dispose();renderer.dispose()}};
}
